```python
import functools
import logging
import random
import time

logger = logging.getLogger(__name__)


def retry(attempts=3, delay=0.5, backoff=2.0, jitter=0.1, exceptions=(Exception,)):
    """Re-run the wrapped function on exception, waiting longer after each failure.

    The delay after failure n is delay * backoff ** n, plus a random amount up
    to `jitter` seconds so that concurrent callers do not retry in lockstep.
    The last attempt's exception propagates unchanged.
    """
    if attempts < 1:
        raise ValueError("attempts must be at least 1")

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            wait = delay
            for attempt in range(1, attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    if attempt == attempts:
                        logger.error(
                            "%s failed after %d attempts: %s",
                            func.__name__,
                            attempts,
                            exc,
                        )
                        raise
                    logger.warning(
                        "%s attempt %d/%d failed (%s); retrying in %.2fs",
                        func.__name__,
                        attempt,
                        attempts,
                        exc,
                        wait,
                    )
                    time.sleep(wait + random.uniform(0, jitter))
                    wait *= backoff

        return wrapper

    return decorator
```

Jitter was already in the version above, but capped at a fixed 0.1s, which stops spreading callers apart once the backoff grows past a second. Scaling it with the current wait keeps the spread proportional:

```python
import functools
import logging
import random
import time

logger = logging.getLogger(__name__)


def retry(attempts=3, delay=0.5, backoff=2.0, jitter=0.25, exceptions=(Exception,)):
    """Re-run the wrapped function on exception, waiting longer after each failure.

    The base delay after failure n is delay * backoff ** n. Each sleep is drawn
    uniformly from +/- `jitter` of that base (jitter=0.25 means +/-25%), so
    callers that fail at the same instant spread out instead of retrying in
    lockstep and hammering a recovering service. The last attempt's exception
    propagates unchanged.
    """
    if attempts < 1:
        raise ValueError("attempts must be at least 1")
    if not 0.0 <= jitter < 1.0:
        raise ValueError("jitter must be in [0.0, 1.0)")

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            wait = delay
            for attempt in range(1, attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    if attempt == attempts:
                        logger.error(
                            "%s failed after %d attempts: %s",
                            func.__name__,
                            attempts,
                            exc,
                        )
                        raise
                    sleep_for = wait * random.uniform(1.0 - jitter, 1.0 + jitter)
                    logger.warning(
                        "%s attempt %d/%d failed (%s); retrying in %.2fs",
                        func.__name__,
                        attempt,
                        attempts,
                        exc,
                        sleep_for,
                    )
                    time.sleep(sleep_for)
                    wait *= backoff

        return wrapper

    return decorator
```

The backoff schedule itself stays deterministic (`wait *= backoff`, not `sleep_for *= backoff`), so jitter perturbs each individual sleep without compounding into wildly divergent total wait times across callers.
